import { test, expect } from '@playwright/test';

test.describe('Itemised Receipt After Checkout', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/checkout');
  });

  test('should display itemised receipt after successful checkout', async ({ page }) => {
    // Add items to cart
    const addToCartButtons = page.getByRole('button', { name: /add to cart/i });
    await expect(addToCartButtons).toHaveLength(2);
    await addToCartButtons.first().click();
    await addToCartButtons.nth(1).click();

    // Proceed to checkout
    const checkoutButton = page.getByRole('button', { name: /proceed to checkout/i });
    await expect(checkoutButton).toBeVisible();
    await checkoutButton.click();

    // Fill in shipping details
    const shippingAddressInput = page.getByLabel(/shipping address/i);
    await shippingAddressInput.fill('123 Main St');

    const cityInput = page.getByLabel(/city/i);
    await cityInput.fill('Anytown');

    const zipInput = page.getByLabel(/zip code/i);
    await zipInput.fill('12345');

    // Fill in payment details
    const cardNumberInput = page.getByLabel(/card number/i);
    await cardNumberInput.fill('4111111111111234');

    const expiryInput = page.getByLabel(/expiry date/i);
    await expiryInput.fill('12/25');

    const cvvInput = page.getByLabel(/cvv/i);
    await cvvInput.fill('123');

    // Click place order
    const placeOrderButton = page.getByRole('button', { name: /place order/i });
    await expect(placeOrderButton).toBeVisible();
    await placeOrderButton.click();

    // Wait for order confirmation
    await page.waitForURL(/.*\/order-confirmation/);

    // Verify receipt is displayed
    const receiptContainer = page.getByRole('region', { name: /order receipt/i });
    await expect(receiptContainer).toBeVisible();

    // Verify itemised list is present
    const receiptItems = page.getByRole('listitem', { name: /item/i });
    await expect(receiptItems).toHaveCount(2);

    // Verify item names and prices
    const item1Name = page.getByText('Product A');
    await expect(item1Name).toBeVisible();

    const item1Price = page.getByText('$19.99');
    await expect(item1Price).toBeVisible();

    const item2Name = page.getByText('Product B');
    await expect(item2Name).toBeVisible();

    const item2Price = page.getByText('$5.00');
    await expect(item2Price).toBeVisible();

    // Verify total amount
    const totalAmount = page.getByText('$24.99');
    await expect(totalAmount).toBeVisible();

    // Verify tax and shipping are itemised
    const taxAmount = page.getByText('$2.50');
    await expect(taxAmount).toBeVisible();

    const shippingAmount = page.getByText('$1.00');
    await expect(shippingAmount).toBeVisible();
  });

  test('should handle empty cart and prevent checkout', async ({ page }) => {
    // Verify empty cart message
    const emptyCartMessage = page.getByText(/your cart is empty/i);
    await expect(emptyCartMessage).toBeVisible();

    // Attempt to click checkout button
    const checkoutButton = page.getByRole('button', { name: /proceed to checkout/i });
    await expect(checkoutButton).toBeDisabled();

    // Verify error message appears
    const errorMessage = page.getByText(/cart cannot be empty/i);
    await expect(errorMessage).toBeVisible();

    // Verify no receipt is displayed
    const receiptContainer = page.getByRole('region', { name: /order receipt/i });
    await expect(receiptContainer).not.toBeVisible();

    // Verify user is redirected to cart page
    await expect(page).toHaveURL(/.*\/cart/);
  });
});
